test_that("instrumentation is unchanged without branch coverage", {
  # Generated by `traced_fixture_bodies()` before branch coverage was added
  expected <- readRDS(test_path("branches/instrumentation-main.rds"))
  pkg <- environmentName(topenv(environment(trace_calls)))
  expected <- lapply(expected, set_namespace, pkg)

  withr::local_options(covr.branch_coverage = NULL)
  expect_identical(traced_fixture_bodies(), expected)
  withr::local_options(covr.branch_coverage = FALSE)
  expect_identical(traced_fixture_bodies(), expected)

  withr::local_options(covr.branch_coverage = TRUE)
  expect_match(
    paste(deparse(traced_fixture_bodies()$f_if), collapse = "\n"),
    paste0(pkg, ":::branch("),
    fixed = TRUE
  )
})

test_that("the branches of `if` are counted, including an implicit `else`", {
  cov <- branch_coverage(
    c(
      "f <- function(x) {",
      "  if (x > 0) 'positive'",
      "  y <- if (x > 10) 'big' else if (x < 0) 'negative' else 'small'",
      "  y",
      "}"
    ),
    "f(1); f(20); f(-1)"
  )
  res <- tally_coverage(cov, by = "branch")
  expect_equal(res$line, c(2, 2, 3, 3, 3, 3))
  expect_equal(res$column, c(3, 3, 8, 8, 31, 31))
  expect_equal(res$label, rep(c("TRUE", "FALSE"), 3))
  expect_equal(res$value, c(2, 1, 1, 2, 1, 1))
  expect_equal(res$functions, rep("f", 6))
})

test_that("the arms of `switch()` are counted, with arms that fall through as one", {
  cov <- branch_coverage(
    c(
      "f <- function(x) switch(x, a = , b = 'ab', c = 'c', 'other')",
      "g <- function(x) switch(x, a = 1, b = 2)",
      "h <- function(i) switch(i, 'one', 'two')"
    ),
    "f('a'); f('b'); f('z'); g('b'); g('z'); g('z'); h(2); h(3)"
  )
  res <- tally_coverage(cov, by = "branch")
  expect_equal(
    res$label,
    c("a, b", "c", "<default>", "a", "b", "<no match>", "1", "2", "<no match>")
  )
  expect_equal(res$value, c(2, 0, 1, 0, 1, 2, 0, 1, 1))
  expect_equal(res$branch, c(1, 2, 3, 1, 2, 3, 1, 2, 3))
})

test_that("`switch()` keeps its value and visibility", {
  env <- local_branch_env(c(
    "f <- function(x) switch(x, a = invisible(1), b = 2)",
    "g <- function(x) switch(x, 'default')"
  ))
  withr::local_options(covr.branch_coverage = TRUE)
  res <- with_coverage(
    list(
      withVisible(env$f("a")),
      withVisible(env$f("b")),
      withVisible(env$f("z")),
      withVisible(env$g("z"))
    ),
    env = env
  )
  expect_equal(
    attr(res, "branches")[[1]]$labels,
    c("a", "b", "<no match>")
  )
  expect_equal(attr(res, "branches")[[1]]$value, c(1, 1, 1))
  # A single unnamed arm is the default of a character `EXPR`, so no default
  # is added
  expect_equal(attr(res, "branches")[[2]]$labels, "1")
  expect_equal(attr(res, "branches")[[2]]$value, 1)

  expect_equal(
    list(
      withVisible(env$f("a")),
      withVisible(env$f("b")),
      withVisible(env$f("z")),
      withVisible(env$g("z"))
    ),
    list(
      list(value = 1, visible = FALSE),
      list(value = 2, visible = TRUE),
      list(value = NULL, visible = FALSE),
      list(value = "default", visible = TRUE)
    )
  )
})

test_that("`switch()` with arms in `...` has no branches", {
  cov <- branch_coverage(
    "f <- function(x, ...) switch(x, ...)",
    "f('a', a = 1)"
  )
  expect_equal(NROW(tally_coverage(cov, by = "branch")), 0)
})

test_that("numbers that select no arm of `switch()` count as no match", {
  cov <- branch_coverage(
    "f <- function(x) switch(x, a = 1, b = 2)",
    "f(1); f(0); f(-1); f(3); f(4); f(NA_real_); f('z')"
  )
  res <- tally_coverage(cov, by = "branch")
  expect_equal(res$label, c("a", "b", "<no match>"))
  expect_equal(res$value, c(1, 0, 6))
})

test_that("conditions `if` rejects signal the same conditions and aren't counted", {
  lines <- "f <- function(x) if (x) 'yes' else 'no'"
  plain <- local_branch_env(lines)
  env <- local_branch_env(lines)
  conditions <- list(NA, logical(), c(TRUE, FALSE), "yes", list(TRUE))
  signalled <- function(f) {
    lapply(conditions, function(x) {
      tryCatch(f(x), condition = function(c) {
        list(class(c), conditionMessage(c))
      })
    })
  }
  expected <- signalled(plain$f)

  withr::local_options(covr.branch_coverage = TRUE)
  cov <- with_coverage(res <- signalled(env$f), env = env)
  expect_identical(res, expected)
  expect_equal(attr(cov, "branches")[[1]]$value, c(0, 0))

  cov <- with_coverage(
    res <- tryCatch(env$f(stop("boom")), error = conditionMessage),
    env = env
  )
  expect_equal(res, "boom")
  expect_equal(attr(cov, "branches")[[1]]$value, c(0, 0))
})

test_that("conditions `if` accepts are counted as `if` interprets them", {
  cov <- branch_coverage(
    "f <- function(x) if (x) 'yes' else 'no'",
    "f(2); f(0); f('T'); f('false'); f(factor('a')); f(c(a = TRUE))"
  )
  expect_equal(tally_coverage(cov, by = "branch")$value, c(4, 2))
})

test_that("classed conditions don't dispatch methods `if` doesn't use", {
  assign(
    "length.covr_test_cond",
    function(x) stop("length dispatched"),
    envir = globalenv()
  )
  assign(
    "is.na.covr_test_cond",
    function(x) stop("is.na dispatched"),
    envir = globalenv()
  )
  withr::defer(
    rm(
      list = c("length.covr_test_cond", "is.na.covr_test_cond"),
      envir = globalenv()
    )
  )
  env <- local_branch_env("f <- function(x) if (x) 'yes' else 'no'")
  withr::local_options(covr.branch_coverage = TRUE)
  cov <- with_coverage(
    res <- env$f(structure(TRUE, class = "covr_test_cond")),
    env = env
  )
  expect_equal(res, "yes")
  expect_equal(attr(cov, "branches")[[1]]$value, c(1, 0))
})

test_that("conditions that use the calling frame work", {
  env <- local_branch_env(
    "f <- function(x) if (missing(x)) nargs() else sys.call()"
  )
  withr::local_options(covr.branch_coverage = TRUE)
  cov <- with_coverage(res <- list(env$f(), env$f(1)), env = env)
  expect_equal(res, list(0L, quote(env$f(1))))
  expect_equal(attr(cov, "branches")[[1]]$value, c(1, 1))
})

test_that("branch coverage doesn't change line coverage", {
  src <- c(
    "f <- function(x) {",
    "  if (x) 'yes'",
    "  switch(x, a = 1, 2)",
    "}"
  )
  cov <- code_coverage(paste(src, collapse = "\n"), "f(TRUE)")
  cov_branches <- branch_coverage(src, "f(TRUE)")
  expect_null(attr(cov, "branches"))
  expect_equal(
    as.data.frame(cov_branches)[-1],
    as.data.frame(cov)[-1]
  )
  expect_equal(percent_coverage(cov_branches), percent_coverage(cov))
})

test_that("percent_coverage() gives the percentage of branches taken", {
  cov <- branch_coverage(
    "f <- function(x) {\n  if (x) 1\n  switch(x, a = 1)\n}",
    "f(TRUE)"
  )
  # `TRUE` and the `switch()`'s "<no match>" for a logical `x`
  expect_equal(percent_coverage(cov, by = "branch"), 50)
})

test_that("tally_coverage(by = 'branch') has no rows without branch coverage", {
  cov <- code_coverage("f <- function(x) if (x) 1", "f(TRUE)")
  res <- tally_coverage(cov, by = "branch")
  expect_equal(NROW(res), 0)
  expect_named(
    res,
    c("filename", "functions", "line", "column", "branch", "label", "value")
  )
})

test_that("branches are saved in trace files and merged", {
  env <- local_branch_env("f <- function(x) if (x) 1")
  withr::local_options(covr.branch_coverage = TRUE)
  dir <- withr::local_tempdir()
  # Like two processes, each saving its own trace
  with_coverage(
    {
      env$f(TRUE)
      save_trace(dir)
      zero_counters()
      env$f(FALSE)
      env$f(FALSE)
      save_trace(dir)
    },
    env = env
  )
  cov <- as_coverage(merge_coverage(list.files(dir, full.names = TRUE)))
  expect_equal(attr(cov, "branches")[[1]]$value, c(1, 2))
  expect_equal(attr(cov, "branches")[[1]]$labels, c("TRUE", "FALSE"))
})

test_that("c() adds the branches of coverage objects", {
  src <- local_r_file("f <- function(x) if (x) 1 else 2")
  withr::local_options(covr.branch_coverage = TRUE)
  cov_true <- file_coverage(src, local_r_file("f(TRUE)"))
  cov_false <- file_coverage(src, local_r_file("f(FALSE); f(FALSE)"))
  cov_g <- file_coverage(
    local_r_file("g <- function(x) if (x) 1"),
    local_r_file("g(TRUE)")
  )

  res <- tally_coverage(c(cov_true, cov_false, cov_g), by = "branch")
  expect_equal(res$value[res$functions == "f"], c(1, 2))
  expect_equal(res$value[res$functions == "g"], c(1, 0))

  withr::local_options(covr.branch_coverage = FALSE)
  cov <- file_coverage(src, local_r_file("f(TRUE)"))
  expect_null(attr(c(cov, cov), "branches"))
})

test_that("branches taken in forked processes are counted", {
  skip_on_os("windows")
  cov <- branch_coverage(
    "f <- function(x) if (x) 1 else 2",
    "f(TRUE); parallel::mccollect(parallel::mcparallel(f(FALSE)))"
  )
  expect_equal(tally_coverage(cov, by = "branch")$value, c(1, 1))
})

test_that("branches are counted when recording tests", {
  withr::local_options(covr.record_tests = TRUE)
  cov <- branch_coverage("f <- function(x) if (x) 1 else 2", "f(TRUE)")
  expect_equal(tally_coverage(cov, by = "branch")$value, c(1, 0))
  expect_length(attr(cov, "tests"), 1)
})

test_that("package_coverage() measures branches", {
  withr::local_options(covr.branch_coverage = TRUE)
  cov <- package_coverage(test_path("TestBranches"))
  res <- tally_coverage(cov, by = "branch")

  expect_equal(unique(res$filename), "R/TestBranches.R")
  # The `if` of `skipped()` is excluded with `# nocov`
  expect_equal(
    res[c("functions", "line", "label", "value")],
    data.frame(
      functions = c(rep("sign_of", 4), rep("describe", 3), rep("forked", 2)),
      line = c(2, 2, 4, 4, 12, 12, 12, 20, 20),
      label = c(
        "TRUE",
        "FALSE",
        "TRUE",
        "FALSE",
        "a, b",
        "z",
        "<no match>",
        "TRUE",
        "FALSE"
      ),
      value = c(1, 1, 0, 1, 1, 0, 1, 1, 0)
    )
  )
  expect_equal(percent_coverage(cov, by = "branch"), 600 / 9)
})

test_that("subsetting coverage subsets its branches", {
  cov <- branch_coverage(
    c("f <- function(x) if (x) 1", "g <- function(x) if (x) 2"),
    "f(TRUE)"
  )
  expect_equal(NROW(tally_coverage(cov[0], by = "branch")), 0)

  functions <- as.data.frame(cov, sort = FALSE)$functions
  res <- tally_coverage(cov[functions == "g"], by = "branch")
  expect_equal(res$functions, c("g", "g"))
  expect_equal(res$value, c(0, 0))
})
